import React, { useCallback, useMemo, useState } from 'react';
import {
  Button,
  Input,
  LinPageLayout,
  dispatchAppToast,
  getActiveCompanyCode,
  getAuthUser,
  useCatalogTableBusy,
  type LinListToolbarActionDef,
} from '@linm-soft-org/linm-web-common-components';
import { UnsavedChangesModal } from '../../../components/form';
import { useArapTtAllocationsPermissions } from '../../../hooks/useArapTtAllocationsPermissions';
import { useUnsavedChangesGuard } from '../../../hooks/useUnsavedChangesGuard';
import {
  allocateArapTt,
  deleteArapTt,
  previewArapTtAuto,
  queryArapTtAllocations,
  type ArapTtAllocationFilter,
  type ArapTtSourceItem,
  type ArapTtTargetItem,
} from '../../../services/kt/arapTtAllocations';
import { useAppDispatch } from '../../../store/hooks';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import { formatDateLocal, formatMoney, parseMoneyInput } from '../../../utils/formatters';
import erp from '../../../styles/erpPage.module.css';
import styles from './PhanBoTienHangHdPage.module.css';

const TEST_ID = 'kt-phan-bo-tien-hang-hd';
const PAGE_ID = 'kt-phan-bo-tien-hang-hd';
const TITLE = 'Phân bổ tiền hàng cho các hóa đơn';

function pad2(n: number): string {
  return n < 10 ? `0${n}` : String(n);
}

function isoToday(): string {
  const d = new Date();
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;
}

function isoFirstOfMonth(): string {
  const d = new Date();
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-01`;
}

function sessionCompany(): string {
  return (getActiveCompanyCode() ?? getAuthUser()?.companyCode ?? '').trim();
}

function normalizePeriod(ngayCt1: string, ngayCt2: string): { ngayCt1: string; ngayCt2: string } | null {
  let a = ngayCt1.trim();
  let b = ngayCt2.trim();
  if (a && !b) b = a;
  if (b && !a) a = b;
  if (!a && !b) return null;
  if (a > b) return { ngayCt1: b, ngayCt2: a };
  return { ngayCt1: a, ngayCt2: b };
}

function cellText(value: string | null | undefined): string {
  const text = (value ?? '').trim();
  return text.length === 0 ? '—' : text;
}

function formatNgayCt(value: string): string {
  const t = value.trim();
  if (!t) return '—';
  const formatted = formatDateLocal(t.length > 10 ? t.slice(0, 10) : t);
  return formatted || t;
}

const PhanBoTienHangHdPage: React.FC = () => {
  const dispatch = useAppDispatch();
  const { canRead, canWrite } = useArapTtAllocationsPermissions();

  const [ngayCt1, setNgayCt1] = useState(isoFirstOfMonth);
  const [ngayCt2, setNgayCt2] = useState(isoToday);
  const [tk, setTk] = useState('131');
  const [maKh, setMaKh] = useState('');
  const [sttRec, setSttRec] = useState('');

  const [sourceItems, setSourceItems] = useState<ArapTtSourceItem[]>([]);
  const [targetItems, setTargetItems] = useState<ArapTtTargetItem[]>([]);
  const [loaiPb, setLoaiPb] = useState(1);
  const [selectedSourceSttRec, setSelectedSourceSttRec] = useState<string | null>(null);
  const [selectedTargetSttRec, setSelectedTargetSttRec] = useState<string | null>(null);
  const [ttDraft, setTtDraft] = useState<Record<string, string>>({});
  const [ttNtDraft, setTtNtDraft] = useState<Record<string, string>>({});

  const [hasLoaded, setHasLoaded] = useState(false);
  const [loadLoading, setLoadLoading] = useState(false);
  const [actionLoading, setActionLoading] = useState(false);
  const [isDirty, setIsDirty] = useState(false);

  const busy = loadLoading || actionLoading;
  const { showTableLoading } = useCatalogTableBusy(busy);
  const { showUnsavedModal, guardedAction, confirmLeave, cancelLeave } = useUnsavedChangesGuard(isDirty, true);

  const selectedSource = useMemo(
    () => sourceItems.find(x => x.sttRec === selectedSourceSttRec) ?? null,
    [sourceItems, selectedSourceSttRec],
  );

  const selectedTarget = useMemo(
    () => targetItems.find(x => x.sttRec === selectedTargetSttRec) ?? null,
    [targetItems, selectedTargetSttRec],
  );

  const appliedFilter = useCallback((): ArapTtAllocationFilter | null => {
    const company = sessionCompany();
    if (!company) {
      dispatchAppToast(dispatch, { message: 'Không xác định đơn vị', type: 'error' });
      return null;
    }
    const period = normalizePeriod(ngayCt1, ngayCt2);
    if (!period) {
      dispatchAppToast(dispatch, { message: 'Chọn khoảng ngày', type: 'error' });
      return null;
    }
    const tkTrim = tk.trim();
    if (!tkTrim) {
      dispatchAppToast(dispatch, { message: 'Chọn tài khoản', type: 'error' });
      return null;
    }
    return {
      ngayCt1: period.ngayCt1,
      ngayCt2: period.ngayCt2,
      tk: tkTrim,
      ...(maKh.trim() ? { maKh: maKh.trim() } : {}),
      ...(sttRec.trim() ? { sttRec: sttRec.trim() } : {}),
    };
  }, [dispatch, maKh, ngayCt1, ngayCt2, sttRec, tk]);

  const applyQueryResult = useCallback(
    (data: { loaiPb: number; sourceItems: ArapTtSourceItem[]; targetItems: ArapTtTargetItem[] }) => {
      setLoaiPb(data.loaiPb);
      setSourceItems(data.sourceItems ?? []);
      setTargetItems(data.targetItems ?? []);
      setTtDraft({});
      setTtNtDraft({});
      setIsDirty(false);
      setHasLoaded(true);
      setSelectedTargetSttRec(null);
      setSelectedSourceSttRec(prev => {
        if (!prev) return null;
        return (data.sourceItems ?? []).some(x => x.sttRec === prev) ? prev : null;
      });
    },
    [],
  );

  const runLoad = useCallback(async () => {
    const filter = appliedFilter();
    if (!filter) return;

    setLoadLoading(true);
    try {
      const data = await queryArapTtAllocations(filter);
      applyQueryResult(data);
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(err, 'Không tải được dữ liệu phân bổ'),
        type: 'error',
      });
    } finally {
      setLoadLoading(false);
    }
  }, [appliedFilter, applyQueryResult, dispatch]);

  const handleFilter = useCallback(() => {
    if (!canRead) return;
    guardedAction(() => void runLoad());
  }, [canRead, guardedAction, runLoad]);

  const handleRefresh = useCallback(() => {
    if (!hasLoaded) return;
    guardedAction(() => void runLoad());
  }, [guardedAction, hasLoaded, runLoad]);

  const handleAllocate = useCallback(async () => {
    const filter = appliedFilter();
    if (!filter) return;
    if (!selectedSourceSttRec) {
      dispatchAppToast(dispatch, {
        message: 'Chọn chứng từ nguồn và nhập số lần này',
        type: 'error',
      });
      return;
    }

    const targets = targetItems
      .map(row => {
        const ttRaw = ttDraft[row.sttRec] ?? String(row.tt ?? 0);
        const ttNtRaw = ttNtDraft[row.sttRec] ?? String(row.ttNt ?? 0);
        const tt = parseMoneyInput(ttRaw);
        const ttNt = parseMoneyInput(ttNtRaw);
        return { sttRec: row.sttRec, tt, ttNt, ngayCt: row.ngayCt };
      })
      .filter(t => t.tt > 0 || t.ttNt > 0);

    if (targets.length === 0) {
      dispatchAppToast(dispatch, {
        message: 'Chọn chứng từ nguồn và nhập số lần này',
        type: 'error',
      });
      return;
    }

    setActionLoading(true);
    try {
      const data = await allocateArapTt({
        ...filter,
        sourceSttRec: selectedSourceSttRec,
        lanPb: 0,
        targets,
      });
      applyQueryResult(data);
      dispatchAppToast(dispatch, { message: 'Phân bổ thành công', type: 'success' });
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(err, 'Không phân bổ được'),
        type: 'error',
      });
    } finally {
      setActionLoading(false);
    }
  }, [
    appliedFilter,
    applyQueryResult,
    dispatch,
    selectedSourceSttRec,
    targetItems,
    ttDraft,
    ttNtDraft,
  ]);

  const runAuto = useCallback(
    async (loai: 1 | 2) => {
      const filter = appliedFilter();
      if (!filter) return;
      if (!selectedSourceSttRec) {
        dispatchAppToast(dispatch, {
          message: 'Chọn chứng từ nguồn và nhập số lần này',
          type: 'error',
        });
        return;
      }

      setActionLoading(true);
      try {
        const data = await previewArapTtAuto({
          ...filter,
          sourceSttRec: selectedSourceSttRec,
          loai,
        });
        setLoaiPb(data.loaiPb);
        setSourceItems(data.sourceItems ?? []);
        const nextTargets = data.targetItems ?? [];
        setTargetItems(nextTargets);
        const nextTt: Record<string, string> = {};
        const nextTtNt: Record<string, string> = {};
        for (const row of nextTargets) {
          if (row.tt) nextTt[row.sttRec] = String(row.tt);
          if (row.ttNt) nextTtNt[row.sttRec] = String(row.ttNt);
        }
        setTtDraft(nextTt);
        setTtNtDraft(nextTtNt);
        setIsDirty(true);
      } catch (err) {
        dispatchAppToast(dispatch, {
          message: getApiErrorMessage(err, 'Không chạy được auto'),
          type: 'error',
        });
      } finally {
        setActionLoading(false);
      }
    },
    [appliedFilter, dispatch, selectedSourceSttRec],
  );

  const handleDelete = useCallback(async () => {
    const filter = appliedFilter();
    if (!filter || !selectedSource || !selectedTarget) return;

    if (selectedTarget.voucher === 1) {
      dispatchAppToast(dispatch, {
        message: 'Bạn không xóa được vì phân bổ từ chức năng tự động các phiếu.',
        type: 'error',
      });
      return;
    }

    if (selectedTarget.daPb <= 0 && selectedTarget.daPbNt <= 0) {
      dispatchAppToast(dispatch, {
        message: 'Chọn dòng nhận đã có phân bổ để xóa',
        type: 'error',
      });
      return;
    }

    const sttRecNo = loaiPb === 1 ? selectedTarget.sttRec : selectedSource.sttRec;
    const sttRecCo = loaiPb === 1 ? selectedSource.sttRec : selectedTarget.sttRec;
    const maKhKey = (selectedSource.maKh || selectedTarget.maKh || maKh).trim();

    setActionLoading(true);
    try {
      const data = await deleteArapTt({
        ...filter,
        sttRecNo,
        sttRecCo,
        tk: filter.tk,
        maKh: maKhKey,
      });
      applyQueryResult(data);
      dispatchAppToast(dispatch, { message: 'Xóa phân bổ thành công', type: 'success' });
    } catch (err) {
      dispatchAppToast(dispatch, {
        message: getApiErrorMessage(err, 'Không xóa được phân bổ'),
        type: 'error',
      });
    } finally {
      setActionLoading(false);
    }
  }, [appliedFilter, applyQueryResult, dispatch, loaiPb, maKh, selectedSource, selectedTarget]);

  const hasAllocateAmount = useMemo(
    () =>
      targetItems.some(row => {
        const tt = parseMoneyInput(ttDraft[row.sttRec] ?? String(row.tt ?? 0));
        const ttNt = parseMoneyInput(ttNtDraft[row.sttRec] ?? String(row.ttNt ?? 0));
        return tt > 0 || ttNt > 0;
      }),
    [targetItems, ttDraft, ttNtDraft],
  );

  const allocateDisabled =
    busy || !canWrite || !selectedSourceSttRec || !hasAllocateAmount;

  const deleteDisabled =
    busy
    || !canWrite
    || !selectedSource
    || !selectedTarget
    || selectedTarget.voucher === 1
    || (selectedTarget.daPb <= 0 && selectedTarget.daPbNt <= 0);

  const autoDisabled = busy || !canWrite || !hasLoaded || !selectedSourceSttRec;

  const toolbarActions = useMemo<LinListToolbarActionDef[]>(
    () => [
      {
        id: 'refresh',
        action: 'refresh',
        placement: 'left',
        variant: 'secondary',
        label: 'Làm mới',
        testId: `${TEST_ID}-toolbar-refresh-btn`,
        disabled: busy,
        onClick: handleRefresh,
      },
      {
        id: 'allocate',
        action: 'edit',
        placement: 'left',
        variant: 'primary',
        label: 'Phân bổ',
        testId: `${TEST_ID}-allocate-btn`,
        disabled: allocateDisabled,
        onClick: () => void handleAllocate(),
      },
      {
        id: 'delete',
        action: 'delete',
        placement: 'left',
        variant: 'secondary',
        label: 'Xóa',
        testId: `${TEST_ID}-delete-btn`,
        disabled: deleteDisabled,
        onClick: () => void handleDelete(),
      },
      {
        id: 'autoValue',
        action: 'edit',
        placement: 'left',
        variant: 'secondary',
        label: 'Auto theo giá trị',
        testId: `${TEST_ID}-auto-value-btn`,
        disabled: autoDisabled,
        onClick: () => void runAuto(1),
      },
      {
        id: 'autoDate',
        action: 'edit',
        placement: 'left',
        variant: 'secondary',
        label: 'Auto theo ngày',
        testId: `${TEST_ID}-auto-date-btn`,
        disabled: autoDisabled,
        onClick: () => void runAuto(2),
      },
    ],
    [
      allocateDisabled,
      autoDisabled,
      busy,
      deleteDisabled,
      handleAllocate,
      handleDelete,
      handleRefresh,
      runAuto,
    ],
  );

  const loaiPbLabel = loaiPb === 2 ? 'Nợ → Có' : 'Có → Nợ';
  const sourceTkLabel = loaiPb === 2 ? 'TK nợ' : 'Tk có';
  const targetTkLabel = loaiPb === 2 ? 'Tk có' : 'TK nợ';

  const sourceEmptyMessage = !hasLoaded ? 'Chọn điều kiện và bấm Lọc' : 'Không có dữ liệu';
  const targetEmptyMessage = sourceEmptyMessage;

  const filterEnter: React.KeyboardEventHandler = e => {
    if (e.key === 'Enter') handleFilter();
  };

  const patchTargetTt = (sttRecKey: string, field: 'tt' | 'ttNt', raw: string) => {
    if (field === 'tt') {
      setTtDraft(prev => ({ ...prev, [sttRecKey]: raw }));
    } else {
      setTtNtDraft(prev => ({ ...prev, [sttRecKey]: raw }));
    }
    setTargetItems(prev =>
      prev.map(row =>
        row.sttRec === sttRecKey
          ? {
              ...row,
              [field]: parseMoneyInput(raw),
            }
          : row,
      ),
    );
    setIsDirty(true);
  };

  if (!canRead) {
    return (
      <div className={erp.voucherListRoot} data-testid={`${TEST_ID}-denied`}>
        <p className={erp.empty}>Bạn không có quyền xem phân bổ tiền hàng cho các hóa đơn.</p>
      </div>
    );
  }

  return (
    <div
      className={erp.voucherListRoot}
      data-catalog-list-page
      data-testid={`${TEST_ID}-page`}
    >
      <LinPageLayout
        kind="catalog"
        testIdPrefix={TEST_ID}
        pageId={PAGE_ID}
        pageClassName={`${erp.catalogListPage} ${erp.voucherListPage}`}
        header={{
          title: TITLE,
          titleIconClass: 'fas fa-exchange-alt',
        }}
        listTitle={TITLE}
        filterMaxWidthPx={1100}
        showTableLoading={showTableLoading}
        skeletonRows={8}
        toolbarProps={{
          testIdPrefix: TEST_ID,
          profile: 'catalog',
          actions: toolbarActions,
        }}
        filters={(
          <>
            <label>
              Từ ngày
              <Input
                type="date"
                value={ngayCt1}
                onChange={e => setNgayCt1(e.target.value)}
                onKeyDown={filterEnter}
                data-testid={`${TEST_ID}-field-ngayCt1`}
              />
            </label>
            <label>
              Đến ngày
              <Input
                type="date"
                value={ngayCt2}
                onChange={e => setNgayCt2(e.target.value)}
                onKeyDown={filterEnter}
                data-testid={`${TEST_ID}-field-ngayCt2`}
              />
            </label>
            <label>
              Tài khoản
              <Input
                value={tk}
                maxLength={30}
                onChange={e => setTk(e.target.value)}
                onKeyDown={filterEnter}
                data-testid={`${TEST_ID}-field-tk`}
              />
            </label>
            <label>
              Mã khách
              <Input
                value={maKh}
                maxLength={30}
                onChange={e => setMaKh(e.target.value)}
                onKeyDown={filterEnter}
                data-testid={`${TEST_ID}-field-maKh`}
              />
            </label>
            <label>
              Stt_Rec
              <Input
                value={sttRec}
                maxLength={30}
                onChange={e => setSttRec(e.target.value)}
                onKeyDown={filterEnter}
                data-testid={`${TEST_ID}-field-sttRec`}
              />
            </label>
            <Button
              variant="primary"
              disabled={busy || !canRead}
              data-testid={`${TEST_ID}-filter-btn`}
              onClick={handleFilter}
            >
              Lọc
            </Button>
          </>
        )}
        modals={(
          <UnsavedChangesModal
            isOpen={showUnsavedModal}
            onStay={cancelLeave}
            onLeave={confirmLeave}
            data-testid={`${TEST_ID}-unsaved-modal`}
          />
        )}
      >
        {hasLoaded ? (
          <div data-testid={`${TEST_ID}-loai-pb`} style={{ marginBottom: 8 }}>
            Loại phân bổ: {loaiPbLabel}
          </div>
        ) : null}

        <h3 data-testid={`${TEST_ID}-source-section`}>Chứng từ đi phân bổ</h3>
        {sourceItems.length === 0 && !showTableLoading ? (
          <div className={erp.empty} data-testid={`${TEST_ID}-source-empty`}>
            {sourceEmptyMessage}
          </div>
        ) : (
          <div className={erp.tableWrapper}>
            <table className={erp.table} data-testid={`${TEST_ID}-source-grid`}>
              <thead>
                <tr>
                  <th>Mã CT</th>
                  <th>Ngày CT</th>
                  <th>Số CT</th>
                  <th>{sourceTkLabel}</th>
                  <th>Mã KH</th>
                  <th>Tên KH</th>
                  <th className={erp.colRight}>Tiền NT</th>
                  <th className={erp.colRight}>Tiền</th>
                  <th className={erp.colRight}>Đã PB NT</th>
                  <th className={erp.colRight}>Đã PB</th>
                  <th className={erp.colRight}>Đã phân bổ lần này (NT)</th>
                  <th className={erp.colRight}>Đã phân bổ lần này</th>
                  <th className={erp.colRight}>Còn lại NT</th>
                  <th className={erp.colRight}>Còn lại</th>
                </tr>
              </thead>
              <tbody>
                {sourceItems.map(row => (
                  <tr
                    key={row.sttRec}
                    className={row.sttRec === selectedSourceSttRec ? erp.rowSelected : undefined}
                    aria-selected={row.sttRec === selectedSourceSttRec}
                    data-testid={`${TEST_ID}-source-row-${row.sttRec}`}
                    onClick={() => setSelectedSourceSttRec(row.sttRec)}
                  >
                    <td>{cellText(row.maCt)}</td>
                    <td>{formatNgayCt(row.ngayCt)}</td>
                    <td>{cellText(row.soCt)}</td>
                    <td>{cellText(row.tk)}</td>
                    <td>{cellText(row.maKh)}</td>
                    <td>{cellText(row.tenKh)}</td>
                    <td className={erp.colRight}>{formatMoney(row.tienNt)}</td>
                    <td className={erp.colRight}>{formatMoney(row.tien)}</td>
                    <td className={erp.colRight}>{formatMoney(row.daPbNt)}</td>
                    <td className={erp.colRight}>{formatMoney(row.daPb)}</td>
                    <td className={erp.colRight}>{formatMoney(row.ttNt)}</td>
                    <td className={erp.colRight}>{formatMoney(row.tt)}</td>
                    <td className={erp.colRight}>{formatMoney(row.clNt)}</td>
                    <td className={erp.colRight}>{formatMoney(row.cl)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        <h3 data-testid={`${TEST_ID}-target-section`} style={{ marginTop: 16 }}>
          Chứng từ nhận phân bổ
        </h3>
        {targetItems.length === 0 && !showTableLoading ? (
          <div className={erp.empty} data-testid={`${TEST_ID}-target-empty`}>
            {targetEmptyMessage}
          </div>
        ) : (
          <div className={erp.tableWrapper}>
            <table className={erp.table} data-testid={`${TEST_ID}-target-grid`}>
              <thead>
                <tr>
                  <th>Mã CT</th>
                  <th>Ngày CT</th>
                  <th>Số CT</th>
                  <th>{targetTkLabel}</th>
                  <th className={erp.colRight}>Tiền NT</th>
                  <th className={erp.colRight}>Tiền</th>
                  <th className={erp.colRight}>Đã PB NT</th>
                  <th className={erp.colRight}>Đã PB</th>
                  <th className={erp.colRight}>Lần này NT</th>
                  <th className={erp.colRight}>Lần này</th>
                  <th className={erp.colRight}>Còn lại NT</th>
                  <th className={erp.colRight}>Còn lại</th>
                  <th />
                </tr>
              </thead>
              <tbody>
                {targetItems.map(row => {
                  const ttValue = ttDraft[row.sttRec] ?? (row.tt ? String(row.tt) : '');
                  const ttNtValue = ttNtDraft[row.sttRec] ?? (row.ttNt ? String(row.ttNt) : '');
                  const isSelected = row.sttRec === selectedTargetSttRec;
                  return (
                    <tr
                      key={row.sttRec}
                      className={isSelected ? erp.rowSelected : undefined}
                      aria-selected={isSelected}
                      data-testid={`${TEST_ID}-target-row-${row.sttRec}`}
                      onClick={() => setSelectedTargetSttRec(row.sttRec)}
                    >
                      <td>{cellText(row.maCt)}</td>
                      <td>{formatNgayCt(row.ngayCt)}</td>
                      <td>{cellText(row.soCt)}</td>
                      <td>{cellText(row.tk)}</td>
                      <td className={erp.colRight}>{formatMoney(row.tienNt)}</td>
                      <td className={erp.colRight}>{formatMoney(row.tien)}</td>
                      <td className={erp.colRight}>{formatMoney(row.daPbNt)}</td>
                      <td className={erp.colRight}>{formatMoney(row.daPb)}</td>
                      <td className={erp.colRight}>
                        <Input
                          className={styles.editableCell}
                          inputMode="decimal"
                          value={ttNtValue}
                          disabled={!canWrite}
                          data-testid={`${TEST_ID}-field-ttNt-${row.sttRec}`}
                          onClick={e => e.stopPropagation()}
                          onChange={e => patchTargetTt(row.sttRec, 'ttNt', e.target.value)}
                        />
                      </td>
                      <td className={erp.colRight}>
                        <Input
                          className={styles.editableCell}
                          inputMode="decimal"
                          value={ttValue}
                          disabled={!canWrite}
                          data-testid={`${TEST_ID}-field-tt-${row.sttRec}`}
                          onClick={e => e.stopPropagation()}
                          onChange={e => patchTargetTt(row.sttRec, 'tt', e.target.value)}
                        />
                      </td>
                      <td className={erp.colRight}>{formatMoney(row.clNt)}</td>
                      <td className={erp.colRight}>{formatMoney(row.cl)}</td>
                      <td>
                        {row.voucher === 1 ? <span>Tự động</span> : null}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </LinPageLayout>
    </div>
  );
};

export default PhanBoTienHangHdPage;
